"""Replace only the simplified Michelin Bib Gourmand icon with approved Bibendum."""
from pathlib import Path
import re
html_path = Path("app/src/main/assets/index.html")
html = html_path.read_text(encoding="utf-8")
pattern = r'(<span class="mic-selected-mark mic-bibendum-mark" aria-hidden="true">)<svg\b.*?</svg>(</span>)'
replacement = r'\g<1><img alt="" width="32" height="32" style="display:block;width:32px;height:32px;object-fit:contain" src="data:image/png;base64,">\g<2>'
updated, count = re.subn(pattern, lambda m: m.group(1) + '<img alt="" width="32" height="32" style="display:block;width:32px;height:32px;object-fit:contain" src="data:image/png;base64,">' + m.group(2), html, flags=re.S)
if count != 1:
    raise SystemExit(f"Expected one Bibendum replacement, found {count}")
html_path.write_text(updated, encoding="utf-8")
print("Replaced simplified Bibendum with approved image.")
